import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, amount: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + amount);
  return result;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return (
    a !== null &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(startOfDay(new Date()));

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const quickOptions = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  function handleSelect(date: Date | null) {
    setSelectedDate(date);
    if (date) {
      onChange?.(date);
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-sm)' }}>
