          <JxChip
            key={option.label}
            active={isSameDay(selectedDate, option.date)}
            onClick={() => handleSelect(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar value={selectedDate} onValueChange={handleSelect} locale="ru-RU" />
    </div>
  );
}

